#!/usr/bin/env bash
# S1 tests for the roles and model adapters of bin/agent: three source roles generate the
# Claude Code (.claude/agents/*.md) and Codex (${CODEX_HOME}/agents/magento-*.toml) adapters,
# model tiers are read from agent/models.env, each cell is overridden with
# KIT_MODEL_<HARNESS>_<TIER>, read-only or write permission decides the Claude tool list,
# a file not generated by the package is left untouched, and old adapters are pruned or
# reported for deletion.
#
# Usage:  bash tests/test-agent-roles.sh
set -Eeuo pipefail
# shellcheck source=tests/lib.sh
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)/lib.sh"

set_profile() {
  sed -i "s|^$1=.*|$1=$2|" "$ROOT/project/profile.env"
}

new_root() {
  sandbox_new
  kit_new shop --domain shop.test > /dev/null
  ROOT="$SANDBOX/shop"
  export CODEX_HOME="$SANDBOX/codex"
  set_profile KIT_GIT_REMOTE origin
  set_profile KIT_GIT_BASE_BRANCH master
  set_profile KIT_GIT_TARGET_BRANCH staging
}

agent() {
  run_in "$ROOT" bin/agent "$@"
}

test_adapters_for_both_harnesses() {
  new_root
  agent install
  assert_status 0 'install generates the adapters and exits 0'
  assert_file "$ROOT/.claude/agents/magento-researcher.md" 'there is a Claude adapter for researcher'
  assert_file "$ROOT/.claude/agents/magento-developer.md" 'there is a Claude adapter for developer'
  assert_file "$ROOT/.claude/agents/magento-reviewer.md" 'there is a Claude adapter for reviewer'
  assert_file "$CODEX_HOME/agents/magento-researcher.toml" 'there is a Codex adapter for researcher'
  assert_file "$CODEX_HOME/agents/magento-developer.toml" 'there is a Codex adapter for developer'
  assert_file "$CODEX_HOME/agents/magento-reviewer.toml" 'there is a Codex adapter for reviewer'
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" '^name: magento-researcher$' 'the Claude adapter has a name'
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" '^description: .+' 'the Claude adapter has a description'
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" '^model: haiku$' 'the fast tier becomes the haiku alias'
  assert_file_matches "$ROOT/.claude/agents/magento-developer.md" '^model: opus$' 'the deep tier becomes the opus alias'
  assert_file_matches "$ROOT/.claude/agents/magento-reviewer.md" '^model: sonnet$' 'the default tier becomes the sonnet alias'
  assert_file_matches "$CODEX_HOME/agents/magento-researcher.toml" '^model = "gpt-5.4-mini"$' 'Codex splits the model from the fast tier'
  assert_file_matches "$CODEX_HOME/agents/magento-researcher.toml" '^model_reasoning_effort = "low"$' 'Codex splits the effort of the fast tier'
  assert_file_matches "$CODEX_HOME/agents/magento-developer.toml" '^model_reasoning_effort = "high"$' 'Codex has the effort of the deep tier'
  assert_file_matches "$CODEX_HOME/agents/magento-developer.toml" '^name = "magento-developer"$' 'the Codex adapter has a name'
}

test_body_copied_verbatim() {
  new_root
  agent install
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" 'You investigate and then answer' 'the Claude adapter copies the role body verbatim'
  assert_file_matches "$CODEX_HOME/agents/magento-researcher.toml" 'You investigate and then answer' 'the Codex adapter copies the role body verbatim'
  assert_file_matches "$CODEX_HOME/agents/magento-developer.toml" 'gate \| command \| PASS/FAIL' 'the developer role body keeps the gate evidence table'
}

test_permission_maps_tools() {
  new_root
  agent install
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" '^tools: Read, Grep, Glob, Bash$' 'the read-only role has no write tool'
  assert_file_matches "$ROOT/.claude/agents/magento-reviewer.md" '^tools: Read, Grep, Glob, Bash$' 'the read-only reviewer role has no write tool'
  assert_file_matches "$ROOT/.claude/agents/magento-developer.md" '^tools: Read, Grep, Glob, Bash, Edit, Write$' 'the write role has Edit and Write'
}

test_model_override_per_cell() {
  new_root
  printf 'KIT_MODEL_CLAUDE_FAST=inherit\nKIT_MODEL_CODEX_DEEP=deepseek-v4-pro:max\n' >> "$ROOT/project/profile.env"
  agent install
  assert_status 0 'install with a model override exits 0'
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" '^model: inherit$' 'the KIT_MODEL_CLAUDE_FAST override takes effect'
  assert_file_matches "$CODEX_HOME/agents/magento-developer.toml" '^model = "deepseek-v4-pro"$' 'the KIT_MODEL_CODEX_DEEP override changes the model'
  assert_file_matches "$CODEX_HOME/agents/magento-developer.toml" '^model_reasoning_effort = "max"$' 'the KIT_MODEL_CODEX_DEEP override changes the effort'
  assert_file_matches "$CODEX_HOME/agents/magento-reviewer.toml" '^model = "gpt-5.3-codex"$' 'a cell that is not overridden keeps the default'
}

test_project_role_gets_codex_prefix() {
  new_root
  mkdir -p "$ROOT/project/agent/roles"
  cat > "$ROOT/project/agent/roles/acme-reviewer.md" <<'EOF'
---
name: acme-reviewer
description: Review the project-specific conventions.
permission: read-only
model: default
---
You are a project-specific role.
EOF
  agent install
  assert_status 0 'install with a project role exits 0'
  assert_file "$ROOT/.claude/agents/acme-reviewer.md" 'the project role has a Claude adapter'
  assert_file "$CODEX_HOME/agents/magento-acme-reviewer.toml" 'the project role has a Codex adapter with the magento- prefix'
  assert_file_matches "$CODEX_HOME/agents/magento-acme-reviewer.toml" '^name = "magento-acme-reviewer"$' 'the Codex adapter uses the prefixed name'
}

test_invalid_role_is_skipped() {
  new_root
  mkdir -p "$ROOT/project/agent/roles"
  cat > "$ROOT/project/agent/roles/thieu-quyen.md" <<'EOF'
---
name: thieu-quyen
description: Role missing permission.
model: default
---
Role body.
EOF
  agent install
  assert_status 0 'install skips the invalid role but still exits 0'
  assert_contains 'read-only or write' 'reports the role that is missing permission'
  assert_absent "$ROOT/.claude/agents/thieu-quyen.md" 'no adapter is generated for the invalid role'
  assert_absent "$CODEX_HOME/agents/magento-thieu-quyen.toml" 'no Codex adapter is generated for the invalid role'
}

test_non_generated_adapter_preserved() {
  new_root
  agent install
  sed -i '/kit:generated/d' "$ROOT/.claude/agents/magento-researcher.md"
  printf 'keep the user copy\n' >> "$ROOT/.claude/agents/magento-researcher.md"
  agent install
  assert_status 0 'the second install exits 0'
  assert_contains 'not generated by bin/agent' 'reports that a file not generated by the package is kept'
  assert_file_matches "$ROOT/.claude/agents/magento-researcher.md" 'keep the user copy' 'does not overwrite the user file'
}

test_stale_generated_adapters_removed() {
  new_root
  agent install
  printf '<!-- kit:generated by bin/agent install -->\nold role\n' > "$ROOT/.claude/agents/role-cu.md"
  printf '# kit:generated by bin/agent install\nname = "magento-role-cu"\n' > "$CODEX_HOME/agents/magento-role-cu.toml"
  agent install
  assert_status 0 'install pruning old adapters exits 0'
  assert_absent "$ROOT/.claude/agents/role-cu.md" 'deletes the Claude adapter with no remaining source'
  assert_absent "$CODEX_HOME/agents/magento-role-cu.toml" 'deletes the Codex adapter with no remaining source'
}

test_legacy_adapters_warned_not_deleted() {
  new_root
  agent install
  printf -- '---\nname: magento-verifier\n---\nold\n' > "$ROOT/.claude/agents/magento-verifier.md"
  printf 'name = "luna-worker"\n' > "$CODEX_HOME/agents/luna-worker.toml"
  agent install
  assert_status 0 'install with old adapters still exits 0'
  assert_contains 'magento-verifier.md' 'reports the old Claude adapter'
  assert_contains 'luna-worker.toml' 'reports the old Codex adapter'
  assert_file "$ROOT/.claude/agents/magento-verifier.md" 'does not delete the old Claude adapter by itself'
  assert_file "$CODEX_HOME/agents/luna-worker.toml" 'does not delete the old Codex adapter by itself'
}

test_install_is_idempotent() {
  new_root
  agent install
  local before_root before_codex
  before_root="$(tree_digest "$ROOT")"
  before_codex="$(tree_digest "$CODEX_HOME")"
  agent install
  assert_status 0 'the second install exits 0'
  assert_not_contains 'Wrote ' 'the second run does not write files again'
  assert_equals "$before_root" "$(tree_digest "$ROOT")" 'the second run changes no file in the Docker root'
  assert_equals "$before_codex" "$(tree_digest "$CODEX_HOME")" 'the second run changes no Codex adapter'
}

test_skill_installed_with_roles() {
  new_root
  agent install
  assert_file "$ROOT/.agents/skills/magento-workflow/SKILL.md" 'installs the magento-workflow skill into .agents/skills'
  assert_file "$ROOT/.claude/skills/magento-workflow/SKILL.md" 'installs the magento-workflow skill into .claude/skills'
  assert_file "$ROOT/.agents/skills/magento-workflow/references/gates.md" 'the skill has the gate matrix reference'
  assert_file "$ROOT/.agents/skills/magento-workflow/references/git-mr.md" 'the skill has the Git and MR reference'
  assert_file "$ROOT/.agents/skills/magento-workflow/references/worktree.md" 'the skill has the worktree reference'
  assert_file_matches "$ROOT/.agents/skills/magento-workflow/SKILL.md" 'not a work sequence' 'SKILL states it is knowledge, not a process'
}

run_tests
finish
